import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"RFC 0089 — Fully public plugins","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0089-fully-public-plugins.md"},"headers":[],"relativePath":"rfcs/0089-fully-public-plugins.md","filePath":"rfcs/0089-fully-public-plugins.md"}'),l={name:"rfcs/0089-fully-public-plugins.md"};function s(n,e,d,r,c,u){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="rfc-0089-—-fully-public-plugins" tabindex="-1">RFC 0089 — Fully public plugins <a class="header-anchor" href="#rfc-0089-—-fully-public-plugins" aria-label="Permalink to &quot;RFC 0089 — Fully public plugins&quot;">​</a></h1><p><strong>Status:</strong> Implemented<br><strong>Date:</strong> August 2026<br><strong>Author:</strong> kasunben<br><strong>Scope:</strong> <code>packages/manifest</code>, runtime middleware, <code>runtime/src/route-guard.ts</code>, <code>runtime/app/(minimal)/layout.tsx</code>, <code>docs/plugin-development.md</code>; builds on RFC 0042 (public plugin page routes) and RFC 0014 (minimal shell mode)<br><strong>Incorporated into plan:</strong> Yes — epic task 2.30.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Add a manifest-level <code>public: true</code> flag that exempts an <strong>entire plugin</strong> from the platform&#39;s session-redirect gate, for plugins that are public by design — a status page, a public wiki, a changelog/blog. This is a thin extension of RFC 0042 (which exempts individual declared route prefixes) and reuses RFC 0014&#39;s existing <code>shell: &quot;minimal&quot;</code> rendering mode rather than introducing a new shell type.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>RFC 0042 lets a plugin carve out narrow, token-protected public pages inside an otherwise private app (a shared document, a published view). It deliberately forbids a <code>/</code> prefix — public exposure must be a small, reviewable declaration, not the whole plugin.</p><p>Some plugins have no private mode at all: their entire purpose is to be visible to anyone, logged in or not (an instance status page, a public wiki, a blog). Building these today means either fighting RFC 0042&#39;s per-route model with awkward workarounds, or accepting that the plugin is unreachable without a session — wrong for the use case. There&#39;s no manifest-driven way to say &quot;this plugin has no auth requirement, period.&quot;</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li>Runtime middleware redirects unauthenticated page requests to <code>/login</code> unless the path matches a declared public route.</li><li><code>publicRoutes</code> (<a href="../../packages/manifest/src/schema.ts">packages/manifest/src/schema.ts:187</a>) lets a plugin declare route prefixes, relative to its own <code>routePrefix</code>, that are exempt from the session gate. The schema explicitly rejects a <code>/</code> prefix (<code>publicRoutes prefix must not be &quot;/&quot;</code>), so a plugin can never be made fully public this way.</li><li><code>matchedPublicPluginRouteId</code> (<a href="../../runtime/src/route-guard.ts">runtime/src/route-guard.ts:72-82</a>) does plain prefix matching against <code>publicRoutes</code> — it has no opinion on what the prefix is, so a <code>/</code> prefix would in fact resolve correctly if the schema allowed it. The exemption mechanism already generalizes to &quot;the whole plugin&quot;; only the manifest validation blocks it.</li><li><code>decidePluginRoute</code> (<a href="../../runtime/src/route-guard.ts">runtime/src/route-guard.ts:40-55</a>) implements the general precedence — disabled plugin → 404, RFC 0065 access-policy denial → 404, <code>adminOnly</code> without <code>console:access</code> → 403, paywall → redirect, else ok — but it is only consulted by the <em>authenticated</em> gate branch in <code>runtime/middleware.ts</code>. The separate public-route fast path (<a href="../../runtime/proxy.ts">runtime/proxy.ts:283-360</a>, reached when <code>matchedPublicPluginRouteId</code> matches) returns before that branch and only checks disabled-plugin status and, for a session-present or monetized request, paywall status — it never consults RFC 0065 restriction. A public route on a restricted plugin is reachable regardless today; this is existing <code>publicRoutes</code> (RFC 0042) behavior, not something this RFC changes.</li><li><code>shell: &quot;minimal&quot;</code> (RFC 0014, <a href="./../../runtime/app/(minimal)/layout.tsx.html">runtime/app/(minimal)/layout.tsx</a>) is chrome-free: no sidebar, header, or footer, the plugin owns the whole viewport. Its doc comment currently states &quot;the session gate still applies... so only authenticated users reach these routes&quot; — true today, not necessarily true after this RFC.</li><li>The default shell (<code>shell: &quot;default&quot;</code> or omitted) renders the platform nav chrome — sidebar/header/footer, user menu — which assumes an authenticated session throughout. It is not designed to render sensibly for an anonymous visitor.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="manifest-field" tabindex="-1">Manifest field <a class="header-anchor" href="#manifest-field" aria-label="Permalink to &quot;Manifest field&quot;">​</a></h3><p>Add optional <code>public</code> to <code>manifest.json</code>:</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;public&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;shell&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minimal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Rules, enforced at manifest validation (same layer as the existing <code>publicRoutes</code> and <code>shell</code>/<code>shellConfig</code> <code>.refine()</code> checks):</p><ul><li><code>public: true</code> requires <code>shell</code> to be <strong>explicitly</strong> <code>&quot;minimal&quot;</code> — an omitted, <code>&quot;default&quot;</code>, or <code>&quot;overlay&quot;</code> <code>shell</code> is rejected. The schema validates cross-field constraints elsewhere rather than silently defaulting one field based on another (see the <code>shellConfig</code> <code>.refine()</code> checks it sits alongside), and both <code>&quot;default&quot;</code> and <code>&quot;overlay&quot;</code> assume a chrome or dialog context built around an authenticated user that a standalone public entry point does not have.</li><li><code>public: true</code> cannot combine with <code>adminOnly: true</code> — contradictory (admin-gated and open-to-anyone).</li><li><code>public: true</code> cannot combine with a paywall tier — contradictory (paid and open-to-anyone).</li><li><code>public: true</code> cannot combine with <code>publicRoutes</code> — redundant and ambiguous about which one governs; a fully public plugin doesn&#39;t need route-level declarations.</li></ul><h3 id="middleware-route-guard-behavior" tabindex="-1">Middleware / route-guard behavior <a class="header-anchor" href="#middleware-route-guard-behavior" aria-label="Permalink to &quot;Middleware / route-guard behavior&quot;">​</a></h3><p>Implemented as sugar over the existing RFC 0042 mechanism rather than a parallel code path:</p><ul><li>At manifest-load time, a plugin with <code>public: true</code> is treated as if it declared <code>publicRoutes: [{ prefix: &#39;/&#39; }]</code>. <code>matchedPublicPluginRouteId</code> requires no changes — <code>underPrefix</code> matching already covers this case correctly, since <code>publicRoutes</code> was never actually incapable of a <code>/</code> prefix, only forbidden from declaring one.</li><li>The public-route fast path&#39;s existing precedence is unchanged: disabled status still resolves to 404 ahead of the exemption, same as <code>publicRoutes</code> today. A <code>platform:owner</code> can still fully disable a nominally-public plugin; <code>public: true</code> removes the <em>default</em> login requirement, it does not remove that override. RFC 0065 access-policy restriction is <strong>not</strong> consulted on this fast path — same gap <code>publicRoutes</code> already has (see &quot;Current state&quot; above) — so restricting a <code>public: true</code> plugin has no effect on its reachability; a <code>platform:owner</code> wanting to fully lock one down must disable it instead. Closing that gap for both mechanisms together is left as an open question below rather than folded into this RFC&#39;s scope.</li><li><code>apiProvider</code>/public <code>/api/*</code> delegation is untouched and orthogonal. <code>public: true</code> only exempts page routes from the session redirect, the same boundary RFC 0042 draws. A public-content plugin that only needs to read data server-side in its page components (the expected case for a status page or wiki) needs no API changes at all. A plugin that also wants an anonymous API surface still opts in via <code>apiProvider</code> separately.</li><li>Session headers: same behavior as RFC 0042 — middleware injects session headers when a valid session exists (so a logged-in visitor to a public wiki still gets their identity, e.g. to show edit controls) and omits them otherwise. The plugin decides what, if anything, to do differently for an authenticated visitor; it must not assume one exists.</li></ul><h3 id="shell-reuse-not-a-new-shell-type" tabindex="-1">Shell reuse, not a new shell type <a class="header-anchor" href="#shell-reuse-not-a-new-shell-type" aria-label="Permalink to &quot;Shell reuse, not a new shell type&quot;">​</a></h3><p><code>shell: &quot;minimal&quot;</code> already provides everything a fully public plugin needs at the rendering layer: no nav chrome, no user-menu assumption, full-viewport content. Requiring it for <code>public: true</code> avoids inventing and maintaining a fourth shell mode, and avoids the real risk in the default shell — its chrome is not audited for anonymous rendering and could leak session-shaped UI (user menu, avatar, account links) into a logged-out view if a public plugin were allowed to use it.</p><p>The only change needed to <code>(minimal)/layout.tsx</code> is to its doc comment: drop the &quot;only authenticated users reach these routes&quot; claim, since it is no longer universally true once a plugin can be both <code>shell: &quot;minimal&quot;</code> and <code>public: true</code>. No rendering logic changes — <code>OfflineBanner</code> and the rest of the minimal layout have no auth dependency to begin with.</p><h3 id="plugin-responsibility" tabindex="-1">Plugin responsibility <a class="header-anchor" href="#plugin-responsibility" aria-label="Permalink to &quot;Plugin responsibility&quot;">​</a></h3><p>Same posture as RFC 0042, generalized to the whole surface instead of a carved-out prefix:</p><ul><li>Render sensibly for an anonymous visitor by default — the common case, not the edge case, for every route under the plugin.</li><li>Treat the presence of injected session headers as an enhancement (show edit/admin affordances to an authenticated, permitted user), never as an assumption.</li><li>Any mutation route must perform its own authorization — the platform gate is gone for the entire plugin, not just a share-link prefix, so there is no implicit &quot;this part must still be private&quot; boundary left to lean on.</li></ul><h3 id="console-visibility" tabindex="-1">Console visibility <a class="header-anchor" href="#console-visibility" aria-label="Permalink to &quot;Console visibility&quot;">​</a></h3><p>Public plugins should be visibly marked in Console&#39;s plugin catalog/detail view (a &quot;Public&quot; badge, similar to how <code>publicRoutes</code> declarations are already surfaced per RFC 0042), so an operator installing or auditing a plugin can immediately see it has no default access control.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><h3 id="a-new-dedicated-shell-type-e-g-shell-public" tabindex="-1">A new dedicated shell type (e.g. <code>shell: &quot;public&quot;</code>) <a class="header-anchor" href="#a-new-dedicated-shell-type-e-g-shell-public" aria-label="Permalink to &quot;A new dedicated shell type (e.g. `shell: &quot;public&quot;`)&quot;">​</a></h3><p>Rejected. <code>shell: &quot;minimal&quot;</code> already provides the correct chrome-free rendering with no auth assumptions baked into its layout; a new shell type would duplicate it for no rendering difference, only to carry the auth semantics that belong in <code>public</code>, a separate manifest axis. Keeping shell (rendering) and public (auth) as independent fields is also more composable: nothing here rules out a future non-minimal public rendering mode without another shell enum value.</p><h3 id="relax-publicroutes-to-allow-directly-skip-the-new-field" tabindex="-1">Relax <code>publicRoutes</code> to allow <code>/</code> directly, skip the new field <a class="header-anchor" href="#relax-publicroutes-to-allow-directly-skip-the-new-field" aria-label="Permalink to &quot;Relax `publicRoutes` to allow `/` directly, skip the new field&quot;">​</a></h3><p>Rejected as the primary interface, though it is exactly the underlying mechanism. A bare <code>publicRoutes: [{ prefix: &#39;/&#39; }]</code> doesn&#39;t read as &quot;this plugin is fully public&quot; to a manifest reviewer, Console, or the plugin catalog the way an explicit <code>public: true</code> does, and it would leave the <code>shell: &quot;minimal&quot;</code> requirement, the <code>adminOnly</code>/paywall conflicts, and the &quot;can&#39;t combine with other publicRoutes entries&quot; rule all unstated. <code>public</code> is implemented in terms of the relaxed mechanism internally, but is the intentional, documented, validated surface.</p><h3 id="let-public-true-also-make-api-public" tabindex="-1">Let <code>public: true</code> also make <code>/api/*</code> public <a class="header-anchor" href="#let-public-true-also-make-api-public" aria-label="Permalink to &quot;Let `public: true` also make `/api/*` public&quot;">​</a></h3><p>Rejected for this RFC. Conflating page-route exposure with API exposure increases blast radius for the common case (read-only public content pages that fetch server-side and need no client-callable API at all) and duplicates a decision already owned by <code>apiProvider</code>. A plugin that needs both simply sets both flags.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ol><li>Should a fully public plugin be reachable without being &quot;installed&quot; in the traditional per-instance sense, or does it always require the normal install/enable flow (this RFC assumes the latter — no change to install/enable semantics, only to the auth gate once enabled)?</li><li>Should Console&#39;s plugin catalog treat <code>public: true</code> plugins as discoverable to anonymous visitors (e.g. listed at a root index), or is each public plugin only reachable if its <code>routePrefix</code> is known/linked externally?</li><li>Root-plugin rewrite (the mechanism that lets one plugin claim <code>/</code>) and <code>public: true</code> plugins — any interaction to define, or are they orthogonal since root-plugin eligibility is about <code>shell: &quot;minimal&quot;</code> already (RFC 0014) and unaffected by the auth flag?</li><li>Should there be a <code>paywallExempt</code>-style escape hatch analogous to RFC 0042&#39;s open question, for a plugin that is mostly paywalled but wants one fully public sub-mode — or does that scenario stay served by <code>publicRoutes</code> instead of <code>public: true</code> (this RFC assumes the latter: <code>public</code> and paywall are mutually exclusive by design, not a hatch to design around)?</li><li>The public-route fast path in <code>runtime/middleware.ts</code> doesn&#39;t consult RFC 0065 access-policy restriction at all — a <code>platform:owner</code> cannot restrict a <code>public: true</code> (or <code>publicRoutes</code>) plugin without fully disabling it. Should a follow-up add a <code>fetchRestrictedPluginIds</code> check to that fast path so restriction and public exposure compose correctly for both mechanisms, or is &quot;restriction doesn&#39;t apply to a route the operator marked public&quot; the intended, if undocumented, semantics? This RFC does not change that existing behavior.</li></ol><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><ol><li>Add <code>public</code> to the manifest schema with the validation rules above (mutually exclusive with <code>adminOnly</code>, paywall, and <code>publicRoutes</code>; requires <code>shell: &quot;minimal&quot;</code> explicitly).</li><li><code>matchedPublicPluginRouteId</code> (<code>runtime/src/route-guard.ts</code>) treats <code>public: true</code> as an implicit <code>publicRoutes: [{ prefix: &#39;/&#39; }]</code> match — no new middleware code path.</li><li>Update <code>(minimal)/layout.tsx</code>&#39;s doc comment to stop asserting the session gate always applies.</li><li>Add Console &quot;public&quot; badge to the Plugins page (desktop table and mobile card layouts).</li><li>Add tests: authenticated, unauthenticated, disabled-plugin (still 404, on both the pure <code>decidePluginRoute</code> function and the real middleware fast path), access-policy-restricted (<code>decidePluginRoute</code> resolves not-found in isolation, but the middleware fast path doesn&#39;t consult it — covered explicitly, not left implicit), and each rejected manifest combination (<code>public</code> + <code>adminOnly</code>, <code>public</code> + paywall, <code>public</code> + <code>publicRoutes</code>, <code>public</code> + <code>shell: &quot;default&quot;</code>/<code>&quot;overlay&quot;</code>).</li><li>Document the field and the plugin-author responsibilities in <code>docs/plugin-development.md</code>, alongside the existing RFC 0042 section.</li></ol><p>No breaking change to existing plugins — <code>public</code> is optional and defaults to unset (current session-gated behavior unchanged).</p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>August 2026</td><td>Initial draft</td></tr><tr><td>0.2</td><td>August 2026</td><td>Implemented as Task 2.30. <code>shell: &quot;minimal&quot;</code> is required explicitly rather than silently defaulted, matching the schema&#39;s existing validation-not-defaulting style. Corrected an inaccurate claim that RFC 0065 access-policy restriction applies to the public-route fast path — it doesn&#39;t, for <code>publicRoutes</code> either; flagged as open question 5 instead of silently fixed.</td></tr></tbody></table>',41)])])}const m=t(l,[["render",s]]);export{p as __pageData,m as default};
